{
  "name": "opencode-usage",
  "version": "0.3.0",
  "description": "Codex, Claude, GLM Coding Plan and OpenCode Go usage limits in the OpenCode TUI sidebar and prompt footer",
  "type": "module",
  "packageManager": "bun@1.4.4",
  "license": "MIT",
  "author": "igorovh",
  "homepage": "https://github.com/igorovh/opencode-usage#readme",
  "bugs": {
    "url": "https://github.com/igorovh/opencode-usage/issues"
  },
  "private": true,
  "repository": {
    "type": "git",
    "url": "git+https://github.com/igorovh/opencode-usage.git"
  },
  "keywords": ["opencode", "opencode-plugin", "tui", "usage", "quota", "rate-limit", "claude", "codex", "glm"],
  "files": ["dist", "src", "tui.ts", "README.md", "LICENSE"],
  "exports": {
    "./tui": "./dist/tui.js"
  },
  "scripts": {
    "compile": "bun scripts/compile.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "check:usage": "bun scripts/check.ts"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5",
    "@opentui/core": ">=0.8.0",
    "@opentui/solid": ">=0.8.0",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.5",
    "@opencode/theme": "2.2.5",
    "@opentui/core": "0.8.2",
    "@opentui/solid": "0.8.2",
    "@types/bun": "1.4.4",
    "solid-js": "1.9.18",
    "typescript": "5.9.3"
  }
}
